def test_login_non_string_password_for_existing_user_is_401():
    """Login with anything other than the correct credentials, including a non-string password for an existing user, returns 401."""
    svc = _svc()
    assert svc.register("carol", "password1")[0] == 201
    for pw in [None, 12345678, b"password1", ["password1"], 1.5]:
