        except Exception as e:  # noqa: BLE001
            raise AssertionError(f"input={('carol', pw)!r} raised {e!r}")
        assert out[0] == 401, f"input={('carol', pw)!r} output={out!r}"


def test_login_non_string_username_is_401():
