    svc = _svc()
    assert svc.register("carol", "password1")[0] == 201
    for user in [None, 123, b"carol"]:
        try:
            out = svc.login(user, "password1")
        except Exception as e:  # noqa: BLE001
            raise AssertionError(f"input={(user, 'password1')!r} raised {e!r}")
